SELECT customers.is_active, customers.country, ROUND((100 * SUM(CASE WHEN orders.channel = 'web' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_web, COUNT(CASE WHEN orders.status = 'SHIPPED' THEN 1 END) AS shipped_count FROM orders RIGHT OUTER JOIN customers ON orders.customer_id = customers.id LEFT OUTER JOIN stores ON orders.store_id = stores.id GROUP BY customers.is_active, customers.country;
